#!/usr/bin/env bash
# Helper invoked by the tmux orchestrator: runs C1 (medical-domain pilot)
# for a single model on one GPU (or via OpenRouter).
#
# Runs External + History on the medical-pilot datasets generated by
# `anchorbench.data.generate --domains medical`. Outputs land in
# results/rebuttal/medical/<suite>/<slug>/ for direct comparison with
# the existing business-domain runs in results/full_benchmark/.

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$REPO_ROOT"

MODEL_ID="${1:?usage: $0 <model_id> <gpu|api>}"
DEVICES="${2:?usage: $0 <model_id> <gpu|api>}"

EXT_DATASET="${EXT_DATASET:-datasets/anchorbench_external_medical_pilot}"
HIST_DATASET="${HIST_DATASET:-datasets/anchorbench_history_medical_pilot}"
OUT_DIR="${OUT_DIR:-results/rebuttal/medical}"
LOG_DIR="$OUT_DIR/_logs"
mkdir -p "$LOG_DIR"
SLUG="${MODEL_ID//\//_}"
LOG="$LOG_DIR/${SLUG}.log"

echo "[$(date -Iseconds)] C1 starting $MODEL_ID on $DEVICES" | tee -a "$LOG"
echo "  ext dataset: $EXT_DATASET" | tee -a "$LOG"
echo "  hist dataset: $HIST_DATASET" | tee -a "$LOG"

if [ "$DEVICES" = "api" ]; then
    # API runner uses SUITE_DATASETS lookup for the suite name, so we use
    # a custom Python invocation that loads the medical datasets directly.
    bash scripts/run_with_env.sh python -c "
import asyncio, os, sys
sys.path.insert(0, 'src')
from pathlib import Path
from anchorbench.eval.io import load_itemspecs, load_promptviews
from anchorbench.eval.evaluator import prepare_items
from anchorbench.inference.async_api import AsyncOpenRouterClient
from anchorbench.runners.api import run_suite_api, run_history_suite_api

api_key = os.environ['OPENROUTER_API_KEY']

async def go():
    client = AsyncOpenRouterClient(api_key=api_key, max_concurrent=16)
    out = Path('$OUT_DIR')

    # External
    pv = load_promptviews('$EXT_DATASET/promptviews_core.jsonl')
    sp = load_itemspecs('$EXT_DATASET/itemspecs.jsonl')
    items = prepare_items(pv, sp, None, 42)
    await run_suite_api(client, '$MODEL_ID', 'external', items, out,
                        max_tokens=512, max_concurrent=16)

    # History
    pv = load_promptviews('$HIST_DATASET/promptviews.jsonl')
    sp = load_itemspecs('$HIST_DATASET/itemspecs.jsonl')
    items = prepare_items(pv, sp, None, 42,
                          conditions=['control_twostage','irrelevant_low',
                                      'irrelevant_high','plausible_low',
                                      'plausible_high'])
    await run_history_suite_api(client, '$MODEL_ID', items, out,
                                 max_tokens=512, max_concurrent=16,
                                 baseline_condition='control_twostage')
    await client.close()

asyncio.run(go())
print('C1 API done')
" 2>&1 | tee -a "$LOG"
else
    export CUDA_VISIBLE_DEVICES="$DEVICES"
    echo "[$(date -Iseconds)] C1/external $MODEL_ID" | tee -a "$LOG"
    bash scripts/run_with_env.sh \
        python -m anchorbench.runners.external \
            --promptviews "$EXT_DATASET/promptviews_core.jsonl" \
            --itemspecs "$EXT_DATASET/itemspecs.jsonl" \
            --model_id "$MODEL_ID" \
            --out_dir "$OUT_DIR/external" \
            --backend vllm \
            --tensor_parallel_size 1 \
            --gpu_memory_utilization 0.85 \
            --batch_size 32 \
            --max_tokens 512 2>&1 | tee -a "$LOG"

    echo "[$(date -Iseconds)] C1/history $MODEL_ID" | tee -a "$LOG"
    bash scripts/run_with_env.sh \
        python -m anchorbench.runners.history \
            --promptviews "$HIST_DATASET/promptviews.jsonl" \
            --itemspecs "$HIST_DATASET/itemspecs.jsonl" \
            --model_id "$MODEL_ID" \
            --out_dir "$OUT_DIR/history" \
            --baseline_condition control_twostage \
            --backend vllm \
            --tensor_parallel_size 1 \
            --gpu_memory_utilization 0.85 \
            --batch_size 1 \
            --max_tokens 512 2>&1 | tee -a "$LOG"
fi

echo "[$(date -Iseconds)] C1 done $MODEL_ID" | tee -a "$LOG"
touch "$LOG_DIR/${SLUG}.done"
